def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}

    # Pieces are either a full 2x2 square or three occupied cells in a 2x2
    # window. The color of an L depends on its missing corner.
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            if all(p in occupied for p in block):
                pieces.append((frozenset(block), 1, True))
            for missing in range(4):
                shape = frozenset(p for i, p in enumerate(block)
                                  if i != missing and p in occupied)
                if len(shape) == 3:
                    color = {0: 2, 1: 4, 2: 3, 3: 2}[missing]
                    pieces.append((shape, color, False))

    by_cell = {p: [] for p in occupied}
    for piece in pieces:
        for p in piece[0]:
            by_cell[p].append(piece)

    best = None
    best_score = -1

    def search(left, chosen, score):
        nonlocal best, best_score
        if not left:
            if score > best_score:
                best, best_score = chosen[:], score
            return

        # Branch on the cell with the fewest currently viable pieces.
        p = min(left, key=lambda q: sum(piece[0] <= left for piece in by_cell[q]))
        options = [piece for piece in by_cell[p] if piece[0] <= left]
        for piece in options:
            search(left - piece[0], chosen + [piece], score + int(piece[2]))

    search(occupied, [], 0)

    output = [[0] * w for _ in range(h)]
    if best is not None:
        for shape, color, _ in best:
            for r, c in shape:
                output[r][c] = color
    return output
